Looking at this logic puzzle, I need to verify the answer using a constraint satisfaction approach. Let me solve it systematically by checking all possible arrangements against the 15 clues.

```python
from itertools import permutations

def solve_puzzle():
    people = ['Blake', 'Harper', 'Morgan', 'Parker', 'Riley']
    colors = ['blue', 'orange', 'red', 'white', 'yellow']
    pets = ['bird', 'cat', 'fish', 'horse', 'rabbit']
    drinks = ['coffee', 'juice', 'milk', 'tea', 'water']
    hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

    for person_perm in permutations(people):
        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    for hobby_perm in permutations(hobbies):
                        if is_valid(person_perm, color_perm, pet_perm, drink_perm, hobby_perm):
                            return person_perm, color_perm, pet_perm, drink_perm, hobby_perm
    return None

def is_valid(people, colors, pets, drinks, hobbies):
    # Create mappings: value -> house position (1-indexed)
    person_to_house = {people[i]: i+1 for i in range(5)}
    color_to_house = {colors[i]: i+1 for i in range(5)}
    pet_to_house = {pets[i]: i+1 for i in range(5)}
    drink_to_house = {drinks[i]: i+1 for i in range(5)}
    hobby_to_house = {hobbies[i]: i+1 for i in range(5)}

    house_to_pet = {i+1: pets[i] for i in range(5)}
    house_to_hobby = {i+1: hobbies[i] for i in range(5)}

    # Check all 15 clues
    if hobby_to_house['hiking'] != color_to_house['yellow']: return False
    if abs(pet_to_house['cat'] - color_to_house['white']) != 1: return False
    if drink_to_house['juice'] + 1 != person_to_house['Riley']: return False
    if house_to_pet[person_to_house['Riley']] == 'bird': return False
    if drink_to_house['water'] != color_to_house['blue']: return False
    if abs(person_to_house['Blake'] - hobby_to_house['rowing']) != 1: return False
    if person_to_house['Harper'] + 1 != pet_to_house['horse']: return False
    if drink_to_house['coffee'] + 1 != pet_to_house['rabbit']: return False
    if abs(person_to_house['Parker'] - drink_to_house['tea']) != 1: return False
    if hobby_to_house['fencing'] != drink_to_house['milk']: return False
    if hobby_to_house['chess'] + 1 != drink_to_house['juice']: return False
    if pet_to_house['rabbit'] + 1 != color_to_house['yellow']: return False
    if house_to_hobby[person_to_house['Parker']] != 'fencing': return False
    if pet_to_house['fish'] != color_to_house['red']: return False
    if person_to_house['Blake'] + 1 != pet_to_house['bird']: return False

    return True

result = solve_puzzle()
if result:
    people, colors, pets, drinks, hobbies = result
    color_to_house = {colors[i]: i+1 for i in range(5)}
    red_house_index = color_to_house['red'] - 1
    person_in_red_house = people[red_house_index]
    print(f"ANSWER: {person_in_red_house}")
else:
    print("ANSWER: UNKNOWN")
